// CollectionCloneOptions defines model for CollectionCloneOptions.
type CollectionCloneOptions struct {
	// Assets Clone the source Collection's Assets and their core properties. If this option is not enabled then the stagMappings and pinRevisions options are ignored.
	Assets *bool `json:"assets,omitempty"`

	// Grants Clone the source Collection's users and their grants. Whether this option is enabled or not, the creator of the cloned Collection (ie. you) will be given an Owner grant in the clone.
	Grants *bool `json:"grants,omitempty"`

	// Labels Clone the source Collection's available labels. You must enable this option AND the assets option for labels to be mapped to Assets in the clone.
	Labels *bool `json:"labels,omitempty"`

	// PinRevisions <b>matchSource:</b> STIGs in the source Collection that are pinned to a specific Revision will be pinned to that Revision in the clone. STIGs that track the latest Revision (unpinned) in the source will be unpinned in the clone.<br><br><b>sourceDefaults:</b> All STIGs in the clone will be pinned to a specific Revision. STIGs that are pinned to a specific Revision in the source Collection will be pinned to that Revision in the clone. STIGs that track the latest Revision in the source will be pinned to the current latest Revision in the clone.
	PinRevisions *CollectionCloneOptionsPinRevisions `json:"pinRevisions,omitempty"`

	// StigMappings <b>withReviews:</b> Assets will be cloned with their current STIG assignments and ALL stored Reviews. This will include Reviews that are no longer associated with a current STIG assignment or are associated with a non-default Revision of a STIG.<br><br><b>withoutReviews:</b> Assets will be cloned with their current STIG assignments but NO stored Reviews will be cloned. All Metrics will be set to zero.<br><br> <b>none:</b> Assets will be cloned with only their core properties and no STIG assignments or Reviews. The pinRevisions option will be ignored.
	StigMappings *CollectionCloneOptionsStigMappings `json:"stigMappings,omitempty"`
}

// CollectionCloneOptionsPinRevisions <b>matchSource:</b> STIGs in the source Collection that are pinned to a specific Revision will be pinned to that Revision in the clone. STIGs that track the latest Revision (unpinned) in the source will be unpinned in the clone.<br><br><b>sourceDefaults:</b> All STIGs in the clone will be pinned to a specific Revision. STIGs that are pinned to a specific Revision in the source Collection will be pinned to that Revision in the clone. STIGs that track the latest Revision in the source will be pinned to the current latest Revision in the clone.
